//! Fixed persisted input, not output generated by the serializer under test.
#![allow(clippy::unwrap_used)]

use serde_json::{Value, json};
use tempfile::TempDir;
use vyane_core::{Ledger, RunQuery};
use vyane_ledger::JsonlLedger;

const RECORDS: &str = include_str!("fixtures/run-record-contract.jsonl");

fn values() -> Vec<Value> {
    RECORDS
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect()
}

#[tokio::test]
async fn fixed_records_preserve_legacy_defaults_and_complete_attempts() {
    let dir = TempDir::new().unwrap();
    let input = dir.path().join("input.jsonl");
    std::fs::write(&input, RECORDS).unwrap();
    let reader = JsonlLedger::new(&input);
    let rows = reader.query(RunQuery::default()).await.unwrap();
    let mut expected = values();
    expected[0]["owner"] = json!("local");
    expected.reverse();
    assert_eq!(serde_json::to_value(&rows).unwrap(), json!(expected));
    assert_eq!(reader.skipped_lines(), 0);
    assert_eq!(rows[1].attempts.len(), 2);
    assert_eq!(rows[1].target, rows[1].attempts[1].target);
    assert_eq!(rows[1].cost_usd, None);
    assert_eq!(rows[2].owner, "local");
    assert_eq!(std::fs::read(&input).unwrap(), RECORDS.as_bytes());

    let output = dir.path().join("output.jsonl");
    let writer = JsonlLedger::new(&output);
    for row in rows.iter().rev() {
        writer.append(row).await.unwrap();
    }
    let disk = std::fs::read_to_string(&output).unwrap();
    assert!(disk.ends_with('\n'));
    let disk_values: Vec<Value> = disk
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    expected.reverse();
    assert_eq!(disk_values, expected);
    let reloaded = writer.query(RunQuery::default()).await.unwrap();
    assert_eq!(
        serde_json::to_value(reloaded).unwrap(),
        serde_json::to_value(rows).unwrap()
    );
}

#[tokio::test]
async fn invalid_utf8_in_json_strings_is_skipped_without_rewriting_input() {
    // Invalid bytes in values AND an ignored key can otherwise become valid
    // JSON after lossy decoding. Each corrupt line must be skipped in full.
    for (field, value) in [
        ("error", "bad-byte-here"),
        ("run_id", "bad-byte-here"),
        ("bad-byte-here", "ignored"),
    ] {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("runs.jsonl");
        let original = values();
        let mut broken = original[1].clone();
        broken[field] = json!(value);
        let serialized = serde_json::to_vec(&broken).unwrap();
        let marker = b"bad-byte-here";
        let index = serialized
            .windows(marker.len())
            .position(|w| w == marker)
            .unwrap();
        let mut corrupt = serialized.clone();
        corrupt.splice(index..index + marker.len(), [0xff]);
        let mut bytes = serde_json::to_vec(&original[0]).unwrap();
        bytes.push(b'\n');
        bytes.extend_from_slice(&corrupt);
        bytes.push(b'\n');
        bytes.extend_from_slice(&serde_json::to_vec(&original[2]).unwrap());
        bytes.push(b'\n');
        std::fs::write(&path, &bytes).unwrap();
        let ledger = JsonlLedger::new(&path);
        let rows = ledger.query(RunQuery::default()).await.unwrap();
        assert_eq!(
            rows.len(),
            2,
            "invalid UTF-8 in {field} must not be silently repaired"
        );
        assert_eq!(rows[0].run_id, original[2]["run_id"].as_str().unwrap());
        assert_eq!(rows[1].run_id, original[0]["run_id"].as_str().unwrap());
        assert_eq!(ledger.skipped_lines(), 1);
        assert_eq!(std::fs::read(&path).unwrap(), bytes);
    }
}

#[tokio::test]
async fn corrupt_tail_and_multiple_invalid_sequences_are_counted_per_line() {
    let dir = TempDir::new().unwrap();
    let path = dir.path().join("runs.jsonl");
    let mut bytes = RECORDS.as_bytes().to_vec();
    let mut broken = serde_json::to_vec(&values()[1]).unwrap();
    // Two distinct invalid sequences in one JSON string remain one bad line.
    let index = broken.windows(9).position(|w| w == b"synthetic").unwrap();
    broken.splice(index..index + 9, [0xff, b'x', 0xc3, b'y']);
    bytes.extend_from_slice(&broken);
    bytes.extend_from_slice(b"\n  \r\n{\"run_id\":\"incomplete");
    std::fs::write(&path, &bytes).unwrap();
    let ledger = JsonlLedger::new(&path);
    assert_eq!(ledger.query(RunQuery::default()).await.unwrap().len(), 3);
    assert_eq!(ledger.skipped_lines(), 2);
    assert_eq!(std::fs::read(&path).unwrap(), bytes);
    // Count describes this scan, not a cumulative lifetime counter.
    assert_eq!(ledger.query(RunQuery::default()).await.unwrap().len(), 3);
    assert_eq!(ledger.skipped_lines(), 2);
}

#[tokio::test]
async fn valid_unicode_and_literal_replacement_character_remain_readable() {
    let dir = TempDir::new().unwrap();
    let path = dir.path().join("runs.jsonl");
    let mut record = values()[2].clone();
    record["error"] = json!("合法字符 � café — \"quoted\"\nnext");
    let bytes = serde_json::to_vec(&record).unwrap();
    // No final newline: a complete final JSON record is valid.
    std::fs::write(&path, &bytes).unwrap();
    let ledger = JsonlLedger::new(&path);
    let rows = ledger.query(RunQuery::default()).await.unwrap();
    assert_eq!(serde_json::to_value(rows).unwrap(), json!([record]));
    assert_eq!(ledger.skipped_lines(), 0);
    assert_eq!(std::fs::read(&path).unwrap(), bytes);
}
